package mz.co.aprendaacodar.blog.controller;
import jakarta.validation.Valid;import mz.co.aprendaacodar.blog.dto.BlogDtos.*;import mz.co.aprendaacodar.blog.service.BlogService;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1") public class BlogController {private final BlogService service;public BlogController(BlogService s){service=s;}
 @GetMapping("/public/blog/posts") public List<PostResponse> posts(){return service.publicPosts();}@GetMapping("/public/blog/posts/{slug}") public PostResponse post(@PathVariable String slug){return service.publicPost(slug);}
 @PostMapping("/admin/blog/posts") @PreAuthorize("hasRole('ADMIN')") public PostResponse create(Authentication a,@Valid @RequestBody PostRequest r){return service.create((UUID)a.getPrincipal(),r);}@PutMapping("/admin/blog/posts/{id}") @PreAuthorize("hasRole('ADMIN')") public PostResponse update(@PathVariable UUID id,@Valid @RequestBody PostRequest r){return service.update(id,r);}@PatchMapping("/admin/blog/posts/{id}/publish") @PreAuthorize("hasRole('ADMIN')") public PostResponse publish(@PathVariable UUID id){return service.publish(id);}@DeleteMapping("/admin/blog/posts/{id}") @PreAuthorize("hasRole('ADMIN')") public void delete(@PathVariable UUID id){service.archive(id);}
 @PostMapping("/blog/posts/{id}/comments") @PreAuthorize("hasRole('STUDENT')") public CommentResponse comment(Authentication a,@PathVariable UUID id,@Valid @RequestBody CommentRequest r){return service.comment((UUID)a.getPrincipal(),id,r.content());}@GetMapping("/blog/posts/{id}/comments") public List<CommentResponse> comments(@PathVariable UUID id){return service.visibleComments(id);}@PatchMapping("/admin/blog/comments/{id}/hide") @PreAuthorize("hasRole('ADMIN')") public void hide(Authentication a,@PathVariable UUID id){service.hideComment((UUID)a.getPrincipal(),id);}
}
